bool minorChebyshev(int body, double jd, double& x, double& y, double& z) {
  const ChebSeg* segs = nullptr;
  int n = 0;
  switch (body) {
    case 0: segs = kPluto; n = 5022; break;
    case 1: segs = kChiron; n = 5022; break;
    case 2: segs = kCeres; n = 5022; break;
    case 3: segs = kPallas; n = 5022; break;
    case 4: segs = kJuno; n = 5022; break;
    case 5: segs = kVesta; n = 5022; break;

    default: return false;
  }
  if (n <= 0 || segs == nullptr) return false;
  if (jd < segs[0].jd0 || jd > segs[n - 1].jd0 + segs[n - 1].span) return false;
  int lo = 0;
  int hi = n - 1;
  while (lo < hi) {
    int mid = (lo + hi) / 2;
    if (segs[mid].jd0 + segs[mid].span < jd) lo = mid + 1;
    else hi = mid;
  }
  const ChebSeg& seg = segs[lo];
  double s = 2.0 * (jd - seg.jd0) / seg.span - 1.0;
  if (s < -1.0) s = -1.0;
  if (s > 1.0) s = 1.0;
  double t0 = 1.0;
  double t1 = s;
  double basis[8];
  basis[0] = t0;
  basis[1] = t1;
  for (int k = 2; k < 8; ++k) {
    double t2 = 2.0 * s * t1 - t0;
    basis[k] = t2;
    t0 = t1;
    t1 = t2;
  }
  x = y = z = 0.0;
  for (int k = 0; k < 8; ++k) {
    x += seg.c[0][k] * basis[k];
    y += seg.c[1][k] * basis[k];
    z += seg.c[2][k] * basis[k];
  }
  return true;
}
